```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

func longestLine(filename string) (string, error) {
	f, err := os.Open(filename)
	if err != nil {
		return "", err
	}
	defer f.Close()

	var longest string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		if len(scanner.Text()) > len(longest) {
			longest = scanner.Text()
		}
	}
	return longest, scanner.Err()
}
```

This function opens the specified file, iterates through each line using a `bufio.Scanner`, and tracks the line with the greatest length. It returns the longest string found or an error if the file cannot be read or scanned.

