Use `position: fixed` for the navbar and track scroll direction with JavaScript.

**HTML:**
```html
<nav id="navbar">Content</nav>
```

**CSS:**
```css
#navbar {
  position: fixed;
  top: 0;
  width: 100%;
  background: white;
  transition: transform 0.3s ease;
  z-index: 1000;
}
.hidden {
  transform: translateY(-100%);
}
```

**JS:**
```javascript
let lastScroll = 0;
const nav = document.getElementById('navbar');

window.addEventListener('scroll', () => {
  const currentScroll = window.pageYOffset;

  if (currentScroll <= 0) {
    nav.classList.remove('hidden');
    return;
  }

  if (currentScroll > lastScroll && currentScroll > 100) {
    nav.classList.add('hidden');
  } else {
    nav.classList.remove('hidden');
  }

  lastScroll = currentScroll;
});
```

The `transition` CSS property ensures smooth sliding. The `lastScroll` variable detects direction: if the current scroll is greater than the previous, the user is scrolling down.

```go
package main

import (
	"fmt"
	"sync"
	"time"
)

func main() {
	jobs := make(chan int, 5)
	results := make(chan int, 5)
	var wg sync.WaitGroup

	// Create 5 workers
	for w := 1; w <= 5; w++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for job := range jobs {
				time.Sleep(time.Duration(job) * time.Millisecond)
				results <- job * 2 // Simulate result
			}
		}(w)
	}

	// Send jobs
	for i := 1; i <= 10; i++ {
		jobs <- i
	}
	close(jobs)

	// Collect results
	for i := 1; i <= 10; i++ {
		fmt.Println("Result:", <-results)
	}

	wg.Wait()
	close(results)
}
```

